-- BullPen Academy — generated course: "Beyond Stocks: ETFs & Crypto" (beginner)
-- Generated by scripts/generate-academy-course.ts. Review before applying.
-- Re-runnable: ON CONFLICT DO NOTHING.

INSERT INTO academy_courses (slug, title, description, icon, color, order_index, difficulty, requires_pro, is_published) VALUES
  ('etfs-and-crypto', 'Beyond Stocks: ETFs & Crypto', 'Stocks aren''t the only asset on BullPen. Learn what ETFs are, how they differ from picking individual stocks, and the basics of crypto and commodities.', 'Layers', 'emerald', 7, 'beginner', FALSE, TRUE)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT
  (SELECT id FROM academy_courses WHERE slug = 'etfs-and-crypto'),
  v.slug, v.title, v.type, v.order_index, v.xp_reward, v.content
FROM (VALUES
  ('what-is-an-etf', 'What is an ETF?', 'read', 0, 10, '{"sections":[{"text":"An ETF, or exchange-traded fund, is like a basket that holds many investments at once. Instead of buying one company''s stock, you buy a single share of the ETF and instantly own a tiny slice of everything inside — sometimes hundreds of stocks or bonds. You can buy and sell it on the stock market during the day, just like a regular stock.","highlightedTerms":[{"term":"ETF","definition":"A fund that holds a basket of investments (like stocks or bonds) and trades on an exchange as a single share you can buy and sell."}]},{"text":"When you pick individual stocks, you''re betting on one company at a time — if it stumbles, your money feels the full hit. An ETF spreads your money across many companies, so one bad apple doesn''t sink the whole basket. This built-in variety is called diversification, and it''s a simple way to lower your risk.","highlightedTerms":[{"term":"diversification","definition":"Spreading your money across many investments so that a single loss doesn''t hurt you too much."}]},{"text":"Running an ETF isn''t free, so the company that manages it charges a small yearly fee called the expense ratio. It''s shown as a percentage — for example, 0.10% means you pay about 10 cents a year for every $100 you have invested. Lower is usually better, since these fees quietly nibble at your returns over time.","highlightedTerms":[{"term":"expense ratio","definition":"The yearly fee an ETF charges to manage your money, shown as a small percentage of what you have invested."}]}],"funFact":"The very first ETF launched in 1993 and was nicknamed the ''Spider'' (SPDR). It still trades today and remains one of the most heavily traded investments in the world."}'::jsonb),
  ('intro-crypto-commodities', 'Intro to Crypto & Commodities', 'read', 1, 10, '{"sections":[{"text":"When you buy a stock, you own a small slice of a real company that earns money by selling products or services. A cryptocurrency is different: there''s no company behind it, no employees, and no earnings to share. Instead, a crypto like Bitcoin is a digital token that lives on a shared computer network, and its price is based purely on what people are willing to pay for it.","highlightedTerms":[{"term":"Cryptocurrency","definition":"A digital asset with no underlying company, earnings, or dividends — its price is based purely on what buyers and sellers agree it''s worth."}]},{"text":"Because a crypto has no earnings or dividends to anchor its value, its price can swing wildly on news, hype, or fear alone. This makes crypto highly volatile, meaning its price can jump or crash much faster than a typical stock. A useful way to picture this is Beta: high-swing assets move far more dramatically than the overall market.","highlightedTerms":[{"term":"Beta","definition":"How much this stock moves compared to the overall market. Beta > 1 means it swings more than the market; < 1 means it''s calmer."}]},{"text":"BullPen also tracks commodities — physical goods like gold, oil, wheat, and copper that are bought and sold in huge global markets. Unlike a company, a barrel of oil doesn''t earn profit; its price rises and falls with real-world supply and demand. Watching commodities helps you understand what''s happening in the wider economy, since they influence everything from gas prices to airline costs.","highlightedTerms":[{"term":"Commodity","definition":"A physical raw material — like gold, oil, wheat, or copper — bought and sold in global markets, priced by real-world supply and demand rather than company earnings."}]},{"text":"So think of it this way: stocks are ownership in a business, crypto is a digital asset with no company attached, and commodities are physical raw materials. Each behaves differently and reacts to different forces, which is why seeing them side by side gives you a fuller picture of the market.","highlightedTerms":[]}],"funFact":"Gold has been used as money for over 4,000 years — long before stocks, banks, or Bitcoin ever existed."}'::jsonb),
  ('beyond-stocks-quiz', 'Quick Check: Beyond Stocks', 'quiz', 2, 20, '{"questions":[{"question":"What is an ETF, in simple terms?","options":["A single company''s stock you buy directly","A basket of many investments you can buy in one purchase, traded like a stock","A savings account offered by a bank","A loan you give to the government"],"correctIndex":1,"explanation":"An ETF (exchange-traded fund) bundles lots of investments together, so buying one share gives you a slice of many companies at once — and it trades on an exchange just like a stock."},{"question":"An ETF has an expense ratio of 0.10%. What does that mean for you?","options":["You pay $10 every time you buy the ETF","The fund charges about $1 per year for every $1,000 you have invested","You earn 0.10% guaranteed profit each year","You must keep the ETF for at least 10 years"],"correctIndex":1,"explanation":"The expense ratio is the yearly fee to run the fund, taken as a percentage of your investment. 0.10% means about $1 per year per $1,000 — so lower is usually better for keeping more of your money."},{"question":"Which statement best describes cryptocurrency for a beginner?","options":["It''s a government-backed currency with guaranteed value","It''s a digital asset that can swing wildly in price and isn''t insured like a bank deposit","It always increases in value over time","It''s the same thing as a savings bond"],"correctIndex":1,"explanation":"Crypto is a digital asset whose price can rise or fall sharply, and it lacks the protections (like FDIC insurance) that bank deposits have — so it''s considered higher risk."}]}'::jsonb),
  ('asset-terms-match', 'Match the Asset Terms', 'match', 3, 15, '{"pairs":[{"term":"ETF","definition":"A basket of investments you can buy and sell like a single stock."},{"term":"Expense Ratio","definition":"The yearly fee, shown as a percentage, for owning a fund."},{"term":"Index Fund","definition":"A fund that copies a market list, like the top 500 U.S. companies."},{"term":"Cryptocurrency","definition":"Digital money that lives online, like Bitcoin, with no bank behind it."},{"term":"Commodity","definition":"A raw physical good you can invest in, like gold or oil."}]}'::jsonb),
  ('stock-etf-or-both', 'Stock, ETF, or Both?', 'scenario', 4, 25, '{"setup":"You''ve decided you believe in the future of tech, but you''re honest with yourself: you have no idea which single company will come out on top. You''ve got $500 to invest. Your goal is simple — you want to own ''tech'' in general, not gamble on one winner. What do you do?","choices":[{"label":"Put all $500 into one tech stock I''ve heard good things about","feedback":"This is tempting because it feels exciting, but it doesn''t match your goal. You said you don''t know which company will win — yet buying one stock is a bet on exactly that. If that single company stumbles, your whole $500 stumbles with it. Great investing starts with matching the tool to the goal, and your goal was broad exposure.","isCorrect":false},{"label":"Buy a tech-sector ETF that holds dozens of tech companies at once","feedback":"Exactly right. An ETF (think of it as a basket that holds many stocks in one purchase) gives you ''tech in general'' instead of a bet on one company. If one company sinks, others may rise, smoothing out the ride. Since your goal was broad exposure without picking winners, this is the tool that fits perfectly.","isCorrect":true},{"label":"Split it: $250 in one stock and $250 in the ETF","feedback":"This isn''t a bad move — the ETF half matches your goal nicely. But the stock half is a bet on one winner, which is the exact thing you said you didn''t want to do. Splitting only makes sense if you actually have strong conviction about a specific company. Since you don''t yet, the pure ETF matches your goal more cleanly.","isCorrect":false}]}'::jsonb)
) AS v(slug, title, type, order_index, xp_reward, content)
ON CONFLICT (course_id, slug) DO NOTHING;
